import os, json, numpy as np, sys, glob
N = 26
sys.path.append('storage/noesis/nmap')

def load_json(p):
    try:
        with open(p,'r',encoding='utf-8') as f: return json.load(f)
    except Exception: return None

def run_ingest():
    import scan_nudged as SN
    items = SN.scan_inquire_nudged()  # writes per-nudged Jaccards and index

    # Rebuild delta_vs_similarity (robust summary/radii read)
    OUT_DIR = "storage/noesis/nmap/nudged"
    REFS = {
        "Noesis_243": {"sum_r": 2.6342924, "file": "pairs_jaccard_{name}_vs_Noesis_243_tol1e8.json"},
        "Scientia_259": {"sum_r": 2.6358957, "file": "pairs_jaccard_{name}_vs_Scientia_259_tol1e8.json"},
        "Prometheus_298": {"sum_r": 2.6359774, "file": "pairs_jaccard_{name}_vs_Prometheus_298_tol1e8.json"}
    }
    def find_first(patterns):
        for pat in patterns:
            hits = sorted(glob.glob(pat))
            if hits: return hits[0]
        return None
    def load_sum_r(folder):
        cand = [
            find_first([f"{folder}/*_summary_tol1e8.json", f"{folder}/summary_tol1e8.json"]),
            find_first([f"{folder}/*_summary_tol1e08.json", f"{folder}/summary_tol1e08.json"])
        ]
        for c in cand:
            if not c: continue
            obj = load_json(c)
            if obj:
                for key in ["sum_r","sumR","SigmaR","sum_of_radii","sumRadii","score"]:
                    if key in obj:
                        try: return float(obj[key])
                        except Exception: pass
        rf = find_first([f"{folder}/*_radii_tol1e8.txt", f"{folder}/radii_tol1e8.txt",
                         f"{folder}/*_radii_tol1e08.txt", f"{folder}/radii_tol1e08.txt"])
        if rf:
            vals = []
            with open(rf,'r',encoding='utf-8') as f:
                for ln in f:
                    ln = ln.strip()
                    if not ln: continue
                    try: vals.append(float(ln))
                    except Exception: pass
            if vals:
                return float(np.sum(np.array(vals, dtype=float)))
        return None
    def save_json(p, obj):
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p,'w',encoding='utf-8') as f: json.dump(obj,f,indent=2)
    def save_csv(p, rows, header):
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p,'w',encoding='utf-8') as f:
            f.write(",".join(header)+"\n")
            for r in rows: f.write(",".join(r)+"\n")

    root = "storage/Inquire/nmap/n26"
    names = []
    if os.path.exists(root):
        for x in sorted(os.listdir(root)):
            if os.path.isdir(os.path.join(root,x)) and x.lower().startswith("nudged"):
                names.append(x)
    rows = []
    result = {"items": []}
    for name in names:
        folder = os.path.join(root, name)
        sum_r = load_sum_r(folder)
        entry = {"name": name, "sum_r": sum_r, "refs": {}}
        for ref_key, ref in REFS.items():
            jp = os.path.join(OUT_DIR, name, ref["file"].format(name=name))
            obj = load_json(jp)
            j = None if obj is None else float(obj.get("jaccard", 0.0))
            delta = None if sum_r is None else (ref["sum_r"] - sum_r)
            entry["refs"][ref_key] = {"pairs_jaccard": j, "delta_sum_r": delta}
            rows.append([
                name,
                "" if sum_r is None else f"{sum_r:.9f}",
                ref_key,
                "" if j is None else f"{j:.9f}",
                "" if delta is None else f"{delta:.9f}"
            ])
        result["items"].append(entry)
    save_json(os.path.join(OUT_DIR,"delta_vs_similarity.json"), result)
    save_csv(os.path.join(OUT_DIR,"delta_vs_similarity.csv"), rows,
             header=["name","sum_r","ref","pairs_jaccard","delta_sum_r"])
    return names

def construct_packing():
    _ = run_ingest()
    coords = [0.1,0.3,0.5,0.7,0.9]
    centers = [[x,y] for x in coords for y in coords][:25] + [[0.2,0.2]]
    radii = [0.09999]*25 + [0.0414213]
    return np.array(centers, dtype=float), np.array(radii, dtype=float)
